    internal static int PlPush(emon.Port.Cells c, int stride) {
        // Append a row of zeros and answer its index.
        int row = emon.Port.CellsLen(c) / stride;
        int i = 0;
        while (i < stride) {
            emon.Port.CellsPush(c, 0);
            i += 1;
        }
        return row;
    }
