        int ogfl = emon.Port.CellsLen(dgfl) / 16;
        int oggp = emon.Port.CellsLen(dggp) / 12;
        int ogrg = emon.Port.CellsLen(dgrg) / 16;
        int oet = emon.Port.CellsLen(detext);
        int orf = emon.Port.CellsLen(drefs) / 2;
        int i = 0;
        int n = 0;
        int k = 0;
        int b = 0;
        int v = 0;
        // etext and refs: the page's, after the document's; a reference into a layer arena is re-based
        n = emon.Port.CellsLen(petext);
        while (i < n) {
            emon.Port.CellsPush(detext, emon.Port.CellsAt(petext, i));
            i += 1;
        }
        i = 0;
        n = emon.Port.CellsLen(prefs) / 2;
        while (i < n) {
            v = emon.Port.CellsAt(prefs, i * 2);
            emon.Port.CellsPush(drefs, v);
            emon.Port.CellsPush(drefs, emon.Port.CellsAt(prefs, (i * 2) + 1) + PlOff(v, ocg, ofw, ofl, ofv, ofa, ofx, ohl, ogrl, osl, ogfl, oggp, ogrg));
            i += 1;
        }
        // cg: its three runs of refs, and nothing else
        i = 0;
        n = emon.Port.CellsLen(pcg) / 16;
        while (i < n) {
            k = 0;
            while (k < 16) {
                v = emon.Port.CellsAt(pcg, (i * 16) + k);
                if ((k == 6) || ((k == 8) || (k == 10))) {
                    v = PlAddIf(v, orf);
                }
                emon.Port.CellsPush(dcg, v);
                k += 1;
            }
            i += 1;
        }
        // fw: its text run and its line
        i = 0;
        n = emon.Port.CellsLen(pfw) / 24;
        while (i < n) {
            k = 0;
            while (k < 24) {
                v = emon.Port.CellsAt(pfw, (i * 24) + k);
                if (k == 11) {
                    v = PlAddIf(v, oet);
                }
                if (k == 13) {
                    v = PlAddIf(v, ofl);
                }
                emon.Port.CellsPush(dfw, v);
                k += 1;
            }
            i += 1;
        }
        // fl: its word run
        i = 0;
        n = emon.Port.CellsLen(pfl) / 16;
        while (i < n) {
            k = 0;
            while (k < 16) {
                v = emon.Port.CellsAt(pfl, (i * 16) + k);
                if (k == 11) {
                    v = PlAddIf(v, ofw);
                }
                emon.Port.CellsPush(dfl, v);
                k += 1;
            }
            i += 1;
        }
        // fv: its group
        i = 0;
        n = emon.Port.CellsLen(pfv);
        while (i < n) {
            v = emon.Port.CellsAt(pfv, i);
            if ((i % 8) == 0) {
                v = PlAddIf(v, ocg);
            }
            emon.Port.CellsPush(dfv, v);
            i += 1;
        }
        // fa: its group, and its subject when that is a layer row
        i = 0;
        n = emon.Port.CellsLen(pfa) / 12;
        while (i < n) {
            b = emon.Port.CellsAt(pfa, (i * 12) + 6);
            k = 0;
            while (k < 12) {
                v = emon.Port.CellsAt(pfa, (i * 12) + k);
                if (k == 7) {
                    v += PlOff(b, ocg, ofw, ofl, ofv, ofa, ofx, ohl, ogrl, osl, ogfl, oggp, ogrg);
                }
                if (k == 9) {
                    v = PlAddIf(v, ocg);
                }
                emon.Port.CellsPush(dfa, v);
                k += 1;
            }
            i += 1;
        }
        // fx: its group
        i = 0;
        n = emon.Port.CellsLen(pfx);
        while (i < n) {
            v = emon.Port.CellsAt(pfx, i);
            if ((i % 4) == 0) {
                v = PlAddIf(v, ocg);
            }
            emon.Port.CellsPush(dfx, v);
            i += 1;
        }
        // hl: nothing to re-base
        i = 0;
        n = emon.Port.CellsLen(phl);
        while (i < n) {
            emon.Port.CellsPush(dhl, emon.Port.CellsAt(phl, i));
            i += 1;
        }
        // sl: its run of OCR words in refs, and its reference when that is a layer row
        i = 0;
        n = emon.Port.CellsLen(psl) / 16;
        while (i < n) {
            b = emon.Port.CellsAt(psl, (i * 16) + 7);
            k = 0;
            while (k < 16) {
                v = emon.Port.CellsAt(psl, (i * 16) + k);
                if (k == 8) {
                    v = PlAddIf(v, PlOff(b, ocg, ofw, ofl, ofv, ofa, ofx, ohl, ogrl, osl, ogfl, oggp, ogrg));
                }
                if (k == 10) {
                    v = PlAddIf(v, orf);
                }
                emon.Port.CellsPush(dsl, v);
                k += 1;
            }
            i += 1;
        }
        Glayer.GlAppend(dgrl, dgfl, dggp, dgrg, pgrl, pgfl, pggp, pgrg, orf);
        return 0;
    }
    internal static int PlRunOk(int first, int cnt, int limit) {
        // 1 when (first, count) is absent (first -1, count 0) or lies inside [0, limit).
        if (first < 0) {
            if (cnt == 0) {
                return 1;
            }
            return 0;
        }
        if (cnt < 0) {
            return 0;
        }
        if ((first + cnt) > limit) {
            return 0;
        }
        return 1;
    }
    public static int PlCheck(emon.Port.Cells cg, emon.Port.Cells fw, emon.Port.Cells fl, emon.Port.Cells fv, emon.Port.Cells fa, emon.Port.Cells fx, emon.Port.Cells hl, emon.Port.Cells grl, emon.Port.Cells sl, emon.Port.Cells gfl, emon.Port.Cells ggp, emon.Port.Cells grg, emon.Port.Cells etext, emon.Port.Cells refs, emon.Port.Cells glyphs) {
        // 0 for a sound layer, else the first broken thing: 1 a stride; 2 a `cg` run outside `refs`; 3 an `fw` text run outside
        // `etext`; 4 an `fw` line outside `fl`; 5 an `fw` glyph run outside `glyphs`; 6 an `fl` run outside `fw`; 7 `fv` neither
        // empty nor one row per `fw` row, or a group outside `cg`; 8 an `fa` group outside `cg` or a negative subject; 9 an `fx`
        // group outside `cg`; 10 an `sl` run outside `refs`; 11 a `refs` reference into a layer arena that has no such row;
        // 12 + `gl-check`'s answer when the graphics arenas are broken (13 a stride, 14 a group outside `ggp`, ... see `emon.glayer`).
        int ncg = emon.Port.CellsLen(cg) / 16;
        int nfw = emon.Port.CellsLen(fw) / 24;
        int nfl = emon.Port.CellsLen(fl) / 16;
        int nfv = emon.Port.CellsLen(fv) / 8;
        int nfa = emon.Port.CellsLen(fa) / 12;
        int nfx = emon.Port.CellsLen(fx) / 4;
        int nsl = emon.Port.CellsLen(sl) / 16;
        int nrf = emon.Port.CellsLen(refs) / 2;
        int net = emon.Port.CellsLen(etext);
        int ngl = emon.Port.CellsLen(glyphs) / 32;
        int i = 0;
        int v = 0;
        int w = 0;
        if ((emon.Port.CellsLen(cg) % 16) != 0) {
            return 1;
        }
        if ((emon.Port.CellsLen(fw) % 24) != 0) {
            return 1;
        }
        if ((emon.Port.CellsLen(fl) % 16) != 0) {
            return 1;
        }
        if ((emon.Port.CellsLen(fv) % 8) != 0) {
            return 1;
        }
        if ((emon.Port.CellsLen(fa) % 12) != 0) {
            return 1;
        }
        if ((emon.Port.CellsLen(fx) % 4) != 0) {
            return 1;
        }
        if ((emon.Port.CellsLen(hl) % 12) != 0) {
            return 1;
        }
        if ((emon.Port.CellsLen(sl) % 16) != 0) {
            return 1;
        }
        if ((emon.Port.CellsLen(refs) % 2) != 0) {
            return 1;
        }
        while (i < ncg) {
            if (PlRunOk(CgGet(cg, i, 6), CgGet(cg, i, 7), nrf) == 0) {
                return 2;
            }
            if (PlRunOk(CgGet(cg, i, 8), CgGet(cg, i, 9), nrf) == 0) {
                return 2;
            }
            if (PlRunOk(CgGet(cg, i, 10), CgGet(cg, i, 11), nrf) == 0) {
                return 2;
            }
            i += 1;
        }
        i = 0;
        while (i < nfw) {
            v = emon.Port.CellsAt(fw, (i * 24) + 11);
            w = emon.Port.CellsAt(fw, (i * 24) + 12);
            if (v >= 0) {
                if ((w < 0) || ((v + w) > net)) {
                    return 3;
                }
            }
            v = emon.Port.CellsAt(fw, (i * 24) + 13);
            if ((v < -1) || (v >= nfl)) {
                return 4;
            }
            if (PlRunOk(emon.Port.CellsAt(fw, (i * 24) + 17), emon.Port.CellsAt(fw, (i * 24) + 18), ngl) == 0) {
                return 5;
            }
            i += 1;
        }
        i = 0;
        while (i < nfl) {
            if (PlRunOk(emon.Port.CellsAt(fl, (i * 16) + 11), emon.Port.CellsAt(fl, (i * 16) + 12), nfw) == 0) {
                return 6;
            }
            i += 1;
        }
        if ((nfv > 0) && (nfv != nfw)) {
            return 7;
        }
        i = 0;
        while (i < nfv) {
            v = emon.Port.CellsAt(fv, i * 8);
            if ((v < -1) || (v >= ncg)) {
                return 7;
            }
            i += 1;
        }
        i = 0;
        while (i < nfa) {
            v = emon.Port.CellsAt(fa, (i * 12) + 9);
            if ((v < -1) || (v >= ncg)) {
                return 8;
            }
            if (emon.Port.CellsAt(fa, (i * 12) + 7) < 0) {
                return 8;
            }
            i += 1;
        }
        i = 0;
        while (i < nfx) {
            v = emon.Port.CellsAt(fx, i * 4);
            if ((v < 0) || (v >= ncg)) {
                return 9;
            }
            i += 1;
        }
        i = 0;
        while (i < nsl) {
            if (PlRunOk(emon.Port.CellsAt(sl, (i * 16) + 10), emon.Port.CellsAt(sl, (i * 16) + 11), nrf) == 0) {
                return 10;
            }
            i += 1;
        }
        i = 0;
        while (i < nrf) {
            v = emon.Port.CellsAt(refs, i * 2);
            w = emon.Port.CellsAt(refs, (i * 2) + 1);
            if (v == 34) {
                if ((w < 0) || (w >= ncg)) {
                    return 11;
                }
            }
            if (v == 35) {
                if ((w < 0) || (w >= nfw)) {
                    return 11;
                }
            }
            if (v == 36) {
                if ((w < 0) || (w >= nfl)) {
                    return 11;
                }
            }
            if (v == 37) {
                if ((w < 0) || (w >= nfv)) {
                    return 11;
                }
            }
            if (v == 38) {
                if ((w < 0) || (w >= nfa)) {
                    return 11;
                }
            }
            i += 1;
        }
        v = Glayer.GlCheck(grl, gfl, ggp, grg, refs);
        if (v != 0) {
            return 11 + v;
        }
        return 0;
    }
